You want a neat piece of code that can pair two items (or people) based on a simple condition.

```javascript
function matchmake(array, key) {
    const map = new Map();
    const pairs = [];

    array.forEach(item => {
        const match = map.get(item[key]);
        if (match) {
            pairs.push([match, item]);
            map.delete(item[key]);
        } else {
            map.set(item[key], item);
        }
    });

    return pairs;
}

